  error = sfnt->init_face( stream, face, face_index, num_params, params );
  if ( !error )
  {
    if ( face->format_tag != TTAG_OTTO )  /* `OTTO'; OpenType/CFF font */
    {
      FT_TRACE2(( "  not an OpenType/CFF font\n" ));
      error = FT_THROW( Unknown_File_Format );
      goto Exit;
    }

    /* if we are performing a simple font format check, exit immediately */
    if ( face_index < 0 )
      return FT_Err_Ok;

    sfnt_format = 1;

    /* now, the font can be either an OpenType/CFF font, or an SVG CEF */
    /* font; in the latter case it doesn't have a `head' table         */
    error = face->goto_table( face, TTAG_head, stream, 0 );
    if ( !error )
    {
      pure_cff = 0;

      /* load font directory */
      error = sfnt->load_face( stream, face, face_index,
                               num_params, params );
      if ( error )
        goto Exit;
    }
    else
    {
      /* load the `cmap' table explicitly */
      error = sfnt->load_cmap( face, stream );
      if ( error )
        goto Exit;
    }

    /* now load the CFF part of the file; */
    /* give priority to CFF2              */
    error = face->goto_table( face, TTAG_CFF2, stream, 0 );
    if ( !error )
    {
      cff2         = 1;
      face->isCFF2 = cff2;
    }

    if ( FT_ERR_EQ( error, Table_Missing ) )
      error = face->goto_table( face, TTAG_CFF, stream, 0 );

    if ( error )
      goto Exit;
  }
  else
  {
    /* rewind to start of file; we are going to load a pure-CFF font */
    if ( FT_STREAM_SEEK( 0 ) )
      goto Exit;
    error = FT_Err_Ok;
  }

  /* now load and parse the CFF table in the file */
  {
    CFF_Font         cff = NULL;
    CFF_FontRecDict  dict;
    FT_Memory        memory = cffface->memory;
    FT_Int32         flags;
    FT_UInt          i;


    if ( FT_NEW( cff ) )
      goto Exit;

    face->extra.data = cff;
    error = cff_font_load( library,
                           stream,
                           face_index,
                           cff,
                           pure_cff,
                           cff2 );
    if ( error )
      goto Exit;

    /* if we are performing a simple font format check, exit immediately */
    /* (this is here for pure CFF)                                       */
    if ( face_index < 0 )
    {
      cffface->num_faces = (FT_Long)cff->num_faces;
      return FT_Err_Ok;
    }

    cff->pshinter = pshinter;
    cff->psnames  = psnames;

    cffface->face_index = face_index & 0xFFFF;

    /* Complement the root flags with some interesting information. */
    /* Note that this is only necessary for pure CFF and CEF fonts; */
    /* SFNT based fonts use the `name' table instead.               */

    cffface->num_glyphs = (FT_Long)cff->num_glyphs;

1052:  sfnt_load_face( FT_Stream      stream,
1105:    FT_TRACE2(( "sfnt_load_face: %08p\n\n", face ));
1608:    FT_TRACE2(( "sfnt_load_face: done\n" ));

  sfnt_load_face( FT_Stream      stream,
                  TT_Face        face,
                  FT_Int         face_instance_index,
                  FT_Int         num_params,
                  FT_Parameter*  params )
  {
    FT_Error      error;
#ifdef TT_CONFIG_OPTION_POSTSCRIPT_NAMES
    FT_Error      psnames_error;
#endif
    FT_Bool       has_outline;
    FT_Bool       is_apple_sbit;
    FT_Bool       is_apple_sbix;
    FT_Bool       ignore_preferred_family    = FALSE;
    FT_Bool       ignore_preferred_subfamily = FALSE;

    SFNT_Service  sfnt = (SFNT_Service)face->sfnt;

    FT_UNUSED( face_instance_index );


    /* Check parameters */

    {
      FT_Int  i;


      for ( i = 0; i < num_params; i++ )
      {
        if ( params[i].tag == FT_PARAM_TAG_IGNORE_PREFERRED_FAMILY )
          ignore_preferred_family = TRUE;
        else if ( params[i].tag == FT_PARAM_TAG_IGNORE_PREFERRED_SUBFAMILY )
          ignore_preferred_subfamily = TRUE;
      }
    }

    /* Load tables */

    /* We now support two SFNT-based bitmapped font formats.  They */
    /* are recognized easily as they do not include a `glyf'       */
    /* table.                                                      */
    /*                                                             */
    /* The first format comes from Apple, and uses a table named   */
    /* `bhed' instead of `head' to store the font header (using    */
    /* the same format).  It also doesn't include horizontal and   */
    /* vertical metrics tables (i.e. `hhea' and `vhea' tables are  */
    /* missing).                                                   */
    /*                                                             */
    /* The other format comes from Microsoft, and is used with     */
    /* WinCE/PocketPC.  It looks like a standard TTF, except that  */
    /* it doesn't contain outlines.                                */
    /*                                                             */

    FT_TRACE2(( "sfnt_load_face: %08p\n\n", face ));

    /* do we have outlines in there? */
#ifdef FT_CONFIG_OPTION_INCREMENTAL
    has_outline = FT_BOOL( face->root.internal->incremental_interface      ||
                           tt_face_lookup_table( face, TTAG_glyf ) != NULL ||
                           tt_face_lookup_table( face, TTAG_CFF ) != NULL  ||
                           tt_face_lookup_table( face, TTAG_CFF2 ) != NULL );
#else
    has_outline = FT_BOOL( tt_face_lookup_table( face, TTAG_glyf ) != NULL ||
                           tt_face_lookup_table( face, TTAG_CFF ) != NULL  ||
                           tt_face_lookup_table( face, TTAG_CFF2 ) != NULL );
#endif

    is_apple_sbit = 0;
    is_apple_sbix = !face->goto_table( face, TTAG_sbix, stream, 0 );

    /* Apple 'sbix' color bitmaps are rendered scaled and then the 'glyf'
     * outline rendered on top.  We don't support that yet, so just ignore
     * the 'glyf' outline and advertise it as a bitmap-only font. */
    if ( is_apple_sbix )
      has_outline = FALSE;

    /* if this font doesn't contain outlines, we try to load */
    /* a `bhed' table                                        */
    if ( !has_outline && sfnt->load_bhed )
